import {ToolRegistry} from './registry.js';

describe('ToolRegistry validation', () => {
  it('rejects input missing a required field without calling the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;

    registry.register(
      {
        name: 'test_tool',
        description: 'A tool for testing',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'success';
      }
    );

    const result = await registry.execute('test_tool', {});

    expect(executorCalls).toBe(0);
    expect(result.result).toContain('location');
    expect(result.result.toLowerCase()).toContain('required');
  });
});

